In this paper, we study first-order projection-free methods for computing $\varepsilon$-approximation solutions to convex optimization problems of form
\begin{equation}\label{problem:CP}
    f^* = \underset{x\in X}{\min}\: f(x).
\end{equation}

Here $X\subset \R^n$ is a high-dimensional compact convex set, $f$ is a convex function, and our goal is to compute an $\varepsilon$-solution $y\in X$ such that $f(y)-f^*\le\varepsilon$. We make the following assumptions concerning the set $X$ and the objective function $f$. Under the Euclidean norm $\|\cdot\|$, we assume that $X$ is compact with diameter
\begin{align}
	\label{eq:D}
	D_X := & \underset{x,y \in X}{\max}\: \norm{x-y} < \infty
\end{align}

and that there exists H\"older exponent $\nu \in (0,1]$ and constant $M_\nu>0$ such that
\begin{equation}
	\label{def:holderCont}
	f(y) \leq f(x) + \ip{\grad f(x),y-x} + \frac{M_\nu}{1+\nu}\norm{x-y}^{1+\nu},\ \forall x,y\in X.
\end{equation}

\begin{algorithm}[t]
	\caption{\label{alg:UCGS} Universal conditional gradient sliding (UCGS) method}
	\footnotesize
	\begin{algorithmic}
		\State
		Start: Choose tolerance $\varepsilon > 0$ and initial iteration $x_0 \in X$.  Set $y_0 = x_0$. 
		\For {$k=1,2,\ldots,$}
		\State Decide $L_k >0$ such that
		\begin{align}
			f(y_k) \leq f(z_k) + \ip{\grad f(z_k),y_k-z_k} + \frac{L_k}{2}\norm{y_k-z_k}^2 + \frac{\varepsilon}{2}\gamma_k\label{def:lk}
		\end{align}
		\State where 
		\begin{align}
			\label{def:gammak} \gamma_k &:= \begin{cases} 1, &k = 1\\ \text{positive solution to } \Gamma_{k-1}(1-\gamma_k)=\frac{L_k\gamma_k^2}{k}, &k > 1 \end{cases}\\
			\label{def:zk} z_k &:= (1-\gamma_k)y_{k-1} + \gamma_k x_{k-1}\\
			\label{def:xk} x_k &:= \text{ACGM}(\grad f(z_k), x_{k-1},\beta_k,\eta_k)\\
			\label{def:yk} y_k &:= (1-\gamma_k)y_{k-1} + \gamma_k x_k\\
			\label{def:Gammakk}\Gamma_k &:= \frac{L_k\gamma_k^2}{k}.
		\end{align}

		\State 
		Compute an approximate solution $s_k$ to the problem 
		\begin{align}
		    \label{def:lkproblem}
		    \min_{x\in X}\ell_k(x) := \Gamma_k \sum_{i=1}^k \frac{\gamma_i}{\Gamma_i}\left( f(z_i) + \ip{\grad f(z_i),x-z_i}\right)
		\end{align}
		such that $\ell_k(s_k) - \min_{x\in X}\ell_k(x)\le \varepsilon_k$. Terminate and output $y_k$ as an approximate solution if
		\begin{align}\label{eq:stopCrit}
			f(y_k) - \ell_k(s_k) + \varepsilon_k \leq \varepsilon.
		\end{align}
		\EndFor
		\\


		\Procedure{$u^+ =$ ACGM}{$g,u,\beta, \eta$} 
		\State Goal: Compute $u^+$ such that $\max_{x\in X}\ip{\grad\phi(u^+), u^+-x}\le \eta$, where
		\begin{align}
		    \label{def:phi}
		    \phi(x):=\ip{g, x} + \frac{\beta}{2}\|x - u\|^2.
		\end{align}
		\State Start: Set $u^0 = u$. 
		\For {$t=1,2,\ldots,$}
		\State Compute a $\delta^t$-approximate solution $v^t$ to the problem $\min_{x\in X}\ip{\nabla\phi(u^{t-1}),x}$ such that
		\begin{equation}\label{eq:cndgsubproblem}
			\ip{g + \beta(u^{t-1}-u),v^t} - \min_{x\in X}\ip{g + \beta(u^{t-1}-u), x}  \leq \delta^t.
		\end{equation}

		\State Terminate with $u^+:=u^{t-1}$ if
		\begin{align}
		    \label{eq:actual_termi}
		    \ip{g+\beta(u^{t-1}-u),u^{t-1}-v^t} + \delta^t \leq \eta.
		\end{align}
		\State Otherwise, compute
% 		\begin{align}
            $
			u^{t}=(1-\alpha^t)u^{t-1}+\alpha^tv^t
% 			, \text{ where }
% 			\alpha^t := \min\: \left\{1,\frac{\ip{g-\beta(u-u^{t-1}),u^{t-1}-v^t}}{\beta\norm{v^t-u^{t-1}}^2}\right\}
			.
			$
% 		\end{align}
		% 			\begin{enumerate}
		% 			    \item Set $u_1 = u$ and $t=1$.
		% 			    \item Let $v_t$ be the optimal solution for the subproblem of

		% 			    \item If $V_{g,u,\beta}(u_t) \leq \eta$, set $u^+ = u_t$ and terminate.
		% 			    \item Set $u_{t+1}=(1-\alpha_t)u_t+\alpha_tv_t$ where $\alpha_t = \min\: \{1,\ip{\beta(u-u_t)-g,v_t-u_t}/(\beta\norm{v_t-u_t}^2)\}$.
		% 			    \item Set $t\leftarrow t+1$ and go to step 2. 
		% 			\end{enumerate}
		\EndFor
		\EndProcedure
	\end{algorithmic}
\end{algorithm}

\begin{align}
	\label{def:alpha}
	\alpha^t := \min\: \left\{1,\frac{\ip{g-\beta(u-u^{t-1}),u^{t-1}-v^t}}{\beta\norm{v^t-u^{t-1}}^2}\right\}.
\end{align}

It is easy to observe that the above $\alpha^t$ is the optimal solution to the exact linesearch problem $\min_{\alpha\in[0,1]}\phi((1-\alpha)u^{t-1} + \alpha v^t)$.


\begin{equation}\label{eq:GammaRelation}
    \Gamma_k = \begin{cases} 1, &k = 1\\ \Gamma_{k-1}(1-\gamma_k), &k > 1\end{cases}.
\end{equation}

Note that for $\nu = 1$, the term $\left(\frac{1-\nu}{1+\nu}\right)^\frac{1-\nu}{1+\nu}$ can be handled using a continuity argument $\lim_{\nu\to 1}\left(\frac{1-\nu}{1+\nu}\right)^\frac{1-\nu}{1+\nu} = 1$. We state an immediate corollary of the above lemma below.

