\begin{theorem}\label{thm:flkDiff}
    Suppose that we apply UCGS described in Algorithm \ref{alg:UCGS} with parameters
    \begin{equation}\label{eq:param}
        \beta_k = L_k\gamma_k,\ \eta_k = \frac{L_k\gamma_kD_X^2}{k},\text{ and }\varepsilon_k = \frac{\sigma L_k\gamma_kD_X^2}{2},
    \end{equation}
    and $\alpha^t$ in \eqref{def:alpha} and $\delta^t = \sigma\beta D_X^2/t$ in the ACGM procedure, where $\sigma\ge 0$ is a parameter related to the accuracy of approximately solving linear objective optimization subproblems.
    Then 
    % we have
    % \begin{align}
    %     f(y_k) - \ell_k(x) \leq \frac{\varepsilon}{2} + \frac{3}{2}L_k\gamma_k^2 D_X^2,\ \forall x\in X.
    % \end{align}
    % Consequently, 
    Algorithm \ref{alg:UCGS} terminates with an $\varepsilon$-solution after at most $N_{\text{grad}}$ gradient evaluations and $N_{\text{lin}}$ linear objective optimizations, where
    \begin{align}\label{eq:evaluations}
    \begin{aligned}
        N_{\text{grad}} :=&\left\lceil16\left(\frac{(3+\sigma)^{\frac{1+\nu}{2}}M_\nu D_X^{1+\nu}}{\varepsilon}\right)^\frac{2}{1+3\nu}\right\rceil
        \text{ and } 
        \\
        N_{\text{lin}} :=& \left\lceil\left(\frac{7}{2}\sigma + 3\right)N_{\text{grad}}^2 + \left(\frac{7}{2}\sigma + 6\right)N_{\text{grad}}\right\rceil.
    \end{aligned} 
    \end{align}
    % As a consequence, the total number of gradient evaluations and linear objective optimizations performed by UCGS to find an $\varepsilon$ solution of \eqref{problem:CP} can be bounded by $\cO((M_{\nu}D_X^{1+\nu}/\varepsilon)^{\frac{2}{1+3\nu}})$ and $\cO((M_{\nu}D_X^{1+\nu}/\varepsilon)^{\frac{4}{1+3\nu}})$ respectively. 
\end{theorem}

