\begin{lemma}
	\label{lem:tele}
	Suppose that $\{a_k\},\{b_k\}\subset\R$ and $\{\gamma_k\}\subset [0,1]$ are sequences that satisfy $\gamma_1=1$ and
	\begin{align}
		\label{eq:tele_assum}
		a_k \le (1-\gamma_k)a_{k-1} + \gamma_k b_k,\ \forall k\ge 1.
	\end{align}
	Then we have
	\begin{align}
		\label{eq:tele_res}
		a_k\le \Gamma_k\sum_{i=1}^{k}\frac{\gamma_i}{\Gamma_i}b_i,\ \forall k\ge 1,\text{ where }\Gamma_k:=\begin{cases}
			1 & \text{ when }k=1
			\\
			\Gamma_{k-1}(1-\gamma_k) & \text{ when }k>1.
		\end{cases}
	\end{align}
\end{lemma}

\begin{proof}
	Dividing both sides of \eqref{eq:tele_assum} by $\Gamma_k$ we obtain a series of inequalities with telescoping terms concerning sequence $\{a_k/\Gamma_k\}$. Summing up we obtain \eqref{eq:tele_res}.
\end{proof}

We proposed to search for such $L_k$ through a backtracking linesearch strategy. In particular, we initialize with any $L_0 \in \R$ and choose $L_1 = 2^i L_0$ where $i$ is the smallest integer such that \eqref{def:lk} is satisfied. At the start of the $k$-th outer iteration where $k>1$, we set $L_k = L_{k-1}/2$ and assess the validity of $L_k$. If it does not satisfy $\eqref{def:lk}$, we keep backtracking and replacing $L_k$ to $2L_k$ until \eqref{def:lk} is satisfies. Through this backtracking linesearch strategy, we ensure that our choice of $L_k$ is adaptive and that performance is independent of the choice of $L_0$. Previous literature \cite{nazari2020backtracking} on backtracking linesearch strategy of CGS require monotonicity of $L_k$ and may suffer from a poorly chosen $L_0$. Second, our termination criterion is based on \eqref{eq:stopCrit}. We can observe immediately that if the parameter $\varepsilon_k\equiv 0$, i.e., $s_k$ is the exact solution to problem \eqref{def:lkproblem}, then when \eqref{eq:stopCrit} is satisfied, $y_k$ will be $\varepsilon$-approximation solution to problem \eqref{problem:CP}.  To see this, note from \eqref{eq:GammaRelation} that
    \begin{equation}\label{eq:gammaSum}
        \Gamma_k \sum_{i=1}^k \frac{\gamma_i}{\Gamma_i} = 1
    \end{equation}
    and consequently
    % \begin{equation}\label{eq:lkBound}
    $$
        f(y_k) - f^* \le f(y_k) - \min_{x\in X}\ell_k(x) =  f(y_k) - \ell_k(s_k).
    $$


\begin{lemma}\label{lem:innerIterUCGS}
    Suppose that $\{\lambda^t\}\in [0,1]$ is any predetermined sequence satisfying $\lambda^1= 1$. In the ACGM procedure, if $\alpha^t$ is chosen such that 
    \begin{align}
        \label{eq:alpha_req}
        \phi(u^t)\le \phi((1-\lambda^t)u^{t-1} + \lambda^tv^t),\ \forall t\ge 1,
    \end{align}
    then we have
    \begin{align}
        \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j}\: \underset{x\in X}{\max}\: \ip{\grad \phi(u^{j-1}),u^{j-1} - x}
        % \\
%        \leq & \delta^1 + \frac{\beta D_X^2}{2} + \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j}\left(\delta^j + \frac{\beta D_X^2\lambda^j}{2} +  \Lambda^{j-1}\sum_{i=1}^{j-1}\frac{\lambda^i}{\Lambda^i}\left(\delta^i + \frac{\beta D_X^2\lambda^i}{2}\right)\right)
        \leq &
        \left[\delta^1 + \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j}\left(\delta^j + \Lambda^{j-1}\sum_{i=1}^{j-1}\frac{\lambda^i}{\Lambda^i}\delta^i\right)\right] 
        \\
        & +
        \frac{\beta D_X^2}{2}\left[1+\sum_{j=2}^t \frac{\lambda^j}{\Lambda^j} \left( \lambda^j + \Lambda^{j-1}\sum_{i=1}^{j-1}\frac{(\lambda^i)^2}{\Lambda^i}\right)\right]
    \end{align}
    for all $t \geq 2$, where
    \begin{align}
        \label{def:Lambda}
        \Lambda^t:=\begin{cases}
            1 & \text{ when }t=1
            \\
            \Lambda^{t-1}(1-\lambda^t) & \text{ when } t>1.
        \end{cases}
    \end{align}
\end{lemma}

\begin{proof}
    Observing that the function $\phi(x)$ in \eqref{def:phi} is a strongly convex function with Lipschitz continuous (with constant $\beta$) gradient, using the assumption \eqref{eq:alpha_req}, and noting the definition of approximate solution $v^t$ in \eqref{eq:cndgsubproblem}, we have
    \begin{align}
    	\label{eq:phiConvex}
    	\begin{aligned}
        &\phi(u^t) - (1-\lambda^t)\phi(u^{t-1}) - \lambda^t(\phi(u^{t-1}) + \ip{\grad \phi(u^{t-1}),x-u^{t-1}})
        \\
        \leq& \phi((1-\lambda^t)u^{t-1} + \lambda^tv^t) - \phi(u^{t-1}) - \lambda^t\ip{\grad\phi(u^{t-1}),x-u^{t-1}}
        \\
        \le & \lambda^t\ip{\grad \phi(u^{t-1}), v^t - u^{t-1}} + \frac{\beta(\lambda^t)^2}{2}\norm{v^t-u^{t-1}}^2 - \lambda^t\ip{\grad \phi(u^{t-1}),x-u^{t-1}}
        \\
        =& \lambda^t\ip{\grad\phi(u^{t-1}),v^t-x} + \frac{\beta(\lambda^t)^2}{2}\norm{v^t-u^{t-1}}^2\\
        \leq& \lambda^t\delta^t +\frac{\beta D_X^2(\lambda^t)^2}{2},\ \forall x\in X, t\ge 1.
	    \end{aligned}
    \end{align}
	Defining $x^*:=\operatorname{argmin}_{x\in X}\phi(x)$, from the above relation we have for any $t\ge 2$ that
	\begin{align}
		\label{eq:tmp1}
		\begin{aligned}
		& \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j} \underset{x\in X}{\max}\:\ip{\grad\phi(u^{j-1}), u^{j-1}-x}
		\\
		\leq& \sum_{j=2}^t \frac{1}{\Lambda^j}[\phi(u^{j-1}) - \phi(x^*)] - \frac{1}{\Lambda^j}[\phi(u^j) - \phi(x^*)] + \frac{\lambda^j}{\Lambda^j}\delta^j + \frac{\beta D_X^2 (\lambda^j)^2}{2\Lambda^j}
		\\
		= & [\phi(u^1) - \phi(x^*)] - \frac{1}{\Lambda^t}[\phi(u^t) - \phi(x^*)] 
		\\
		& + \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j}[\phi(u^{j-1}) - \phi(x^*)] + \frac{\lambda^j}{\Lambda^j}\delta^j + \frac{\beta D_X^2(\lambda^j)^2}{2\Lambda^j}
		\\
		\le & [\phi(u^1) - \phi(x^*)] + \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j}[\phi(u^{j-1}) - \phi(x^*)] + \frac{\lambda^j}{\Lambda^j}\delta^j + \frac{\beta D_X^2(\lambda^j)^2}{2\Lambda^j}.
		\end{aligned}
	\end{align}
	Here in the equality we use the following observations from the definition of $\Lambda^t$ in \eqref{def:Lambda}: $1/\Lambda^1 = 1$ and $1/\Lambda^j = 1/\Lambda^{j-1} + \lambda^j/\Lambda^j$ for all $j\ge 2$, 
%	\begin{align}
%		\frac{1}{\Lambda^j} = \frac{1}{\Lambda^{j-1}} + \frac{\lambda^j}{\Lambda^{j}},\ \forall j\ge 2,
%	\end{align}

    To finish the proof it suffices to bound $\phi(u^{j-1})-\phi(x^*)$ for any $j\ge 2$. Observing that $\phi(x)$ in \eqref{def:phi} is strongly convex and quadratic with
    \begin{equation}
        \frac{\beta}{2}\norm{x-u^{t-1}}^2 = \phi(x) - (\phi(u^{t-1})+\ip{\grad \phi(u^{t-1}), x-u^{t-1}}),\ \forall x\in X, t\ge 1,
    \end{equation}
    we have from \eqref{eq:phiConvex} (with $x = x^*$) that
    \begin{equation}\label{eq:telescopingBound}
        [\phi(u^t)-\phi(x^*)] - (1-\lambda^t)[\phi(u^{t-1})-\phi(x^*)] \leq \lambda^t\delta^t + \frac{\beta D_X^2(\lambda^t)^2}{2} - \frac{\beta\lambda^t}{2}\norm{x^*-u^{t-1}}^2.
    \end{equation}
    Applying Lemma \ref{lem:tele} to the above recurrence relation and ignoring negative terms at the right hand side, we have
    \begin{align}\label{eq:simplePhiBound}
        \phi(u^t) - \phi(x^*) \leq \Lambda^t\sum_{i=1}^t \frac{\lambda^i}{\Lambda^i}\delta^i + \frac{\beta D_X^2(\lambda^i)^2}{2\Lambda^i},\ \forall t\ge 1.
    \end{align}
	We conclude the lemma immediately by applying the above bound to \eqref{eq:tmp1} and rearranging terms.
%	\begin{align}
%			& \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j} \underset{x\in X}{\max}\:\ip{\grad\phi(u^{j-1}), u^{j-1}-x}
%			\\
%			\le & \delta^1 + \frac{\beta D_X^2}{2} + \sum_{j=2}^t \frac{\lambda^j}{\Lambda^j}\Lambda^{j-1}\left(\sum_{i=1}^{j-1} \frac{\lambda^i}{\Lambda^i}\delta^i + \frac{\beta D_X^2(\lambda^i)^2}{2\Lambda^i}\right) + \frac{\lambda^j}{\Lambda^j}\delta^j + \frac{\beta D_X^2(\lambda^j)^2}{2\Lambda^j}.
%	\end{align}
\end{proof}

\begin{proposition}\label{prop:innerIterUCGS}
	In the ACGM procedure, at termination we have
	\begin{align}
	    \label{eq:innerIterUCGS_OC}
	    \underset{x\in X}{\max}\: \ip{\grad \phi(u^+), u^+-x} \le \eta.
	\end{align}
	Moreover, if $\delta^t = \sigma\beta D_X^2/t$ for certain $\sigma\ge 0$ and $\alpha^t$ is chosen such that 
	\begin{align}
		\label{eq:alpha_req_2t1}
		\phi(u^t) \le \phi\left(\frac{t-1}{t+1}u^{t-1} + \frac{2}{t+1}v^t\right),
	\end{align}
	then we have for any $t\ge 1$ that
    \begin{align}
        \label{eq:termi_rate}
        \begin{aligned}
        \underset{j=1, \dots, t+1}{\min}\:\ip{\grad \phi(u^{j-1}), u^{j-1}-v^{j}}\le & \underset{j=1, \dots, t+1}{\min}\:\underset{x\in X}{\max}\: \ip{\grad \phi(u^{j-1}), u^{j-1}-x}
        \\
        \le & \frac{6(\sigma+1)\beta D_X^2}{t}.
        \end{aligned}
    \end{align}
    Specially, it takes at most
    \begin{align}
        \label{def:T}
        T := 1 + \left\lceil \frac{(7\sigma+6)\beta D_X^2}{\eta}\right\rceil 
    \end{align}
    iterations for the ACGM procedure to terminate.
\end{proposition}

\begin{proof}
    From the definition of the approximate solution $v^t$ in \eqref{eq:cndgsubproblem}, if the termination criterion in \eqref{eq:actual_termi} of the ACGM procedure is satisfied, then the output $u^+=u^{t-1}$ satisfies
    \begin{align}
        \max_{x\in X}\ip{\grad \phi(u^{t-1}), u^{t-1}-x} &= \max_{x\in X}\ip{\grad \phi(u^{t-1}), u^{t-1}-v^t} + \ip{\grad \phi(u^{t-1}), v^t - x}
        \\
        &\le  (\eta - \delta^t) + \delta^t = \eta.
    \end{align}
    Therefore \eqref{eq:innerIterUCGS_OC} holds. To conclude the proposition it suffices to estimate the rate of convergence of $\underset{x\in X}{\max}\: \ip{\grad \phi(u^{t-1}), u^{t-1}-x}$. To analyze the rate, let us choose $\lambda^t = 2/(t+1)$ and apply Lemma \ref{lem:innerIterUCGS}. Then $\Lambda^t = 2/(t(t+1))$ and
    \begin{align}
        & \sum_{j=2}^t j\cdot\:\underset{x\in X}{\max}\ip{\phi(u^{j-1}),u^{j-1}-x}
        \\
%        \leq& \left[\delta^1 + \sum_{j=2}^t \left(j\delta^j + \frac{2}{j-1}\sum_{i=1}^{j-1} i \delta^i\right)\right] + \frac{\beta D_X^2}{2}\left[1+\sum_{j=2}^t\left( \frac{2j}{j+1} + \frac{2}{j-1}\sum_{i=1}^{j-1} \frac{2i}{i+1}\right)\right]
        \leq& \sigma\beta D_X^2\left[1 + \sum_{j=2}^t \left(1 + \frac{2}{j-1}\sum_{i=1}^{j-1} 1\right)\right] + \frac{\beta D_X^2}{2}\left[1+\sum_{j=2}^t\left( \frac{2j}{j+1} + \frac{2}{j-1}\sum_{i=1}^{j-1} \frac{2i}{i+1}\right)\right]
        \\
        < &  \sigma\beta D_X^2(3t-2)+ \frac{\beta D_X^2}{2}(6t-5),\ \forall t\ge 2.
    \end{align}
    Noting that $\sum_{j=2}^t j = (t+2)(t-1)/2$, we have
%    , after rearranging, we have 
%    \begin{align}
%        \underset{j =2, \dots, t}{\min}\:\underset{x\in X}{\max}&\: \ip{\grad \phi(u^{j-1}), u^{j-1}-x}\\
%        \leq& \frac{2}{(t-1)(t+2)} \left(\sum_{j=2}^t j\delta^j + \frac{2}{j-1}\sum_{i=1}^{j-1}i \delta^i\right) + \frac{\beta D_X^2(6t-5)}{(t-1)(t+2)}.
%    \end{align}
%    A change of indexing allows us to conclude that
	\begin{align}
		\underset{j=2, \dots, t}{\min}\:\underset{x\in X}{\max}\: \ip{\grad \phi(u^{j-1}), u^{j-1}-x} \le & \frac{2}{(t+2)(t-1)}\sum_{j=2}^t j\cdot\:\underset{x\in X}{\max}\ip{\phi(u^{j-1}),u^{j-1}-x}
		\\
%		\le & \frac{2\sigma\beta D_X^2(3t-2)}{(t+2)(t-1)}+ \frac{\beta D_X^2(6t-5)}{(t+2)(t-1)}
%		\\
%		< & \frac{6\sigma\beta D_X^2}{t-1}+ \frac{6\beta D_X^2}{t-1}
%		\\
		< & \frac{6(\sigma+1)\beta D_X^2}{t-1}
		,\ \forall t\ge 2.
	\end{align}
	Using the above result and observing that 
	\begin{align}
		\underset{j=1, \dots, t+1}{\min}\:\ip{\grad \phi(u^{j-1}), u^{j-1}-v^{j}} \le & 
		\underset{j=1, \dots, t+1}{\min}\:\underset{x\in X}{\max}\: \ip{\grad \phi(u^{j-1}), u^{j-1}-x}
		\\
		\le & 
		\underset{j=2, \dots, t+1}{\min}\:\underset{x\in X}{\max}\: \ip{\grad \phi(u^{j-1}), u^{j-1}-x},\ \forall t\ge 1
	\end{align}
	we conclude \eqref{eq:termi_rate}. Moreover, from \eqref{eq:termi_rate} and noting the choice of $\delta^t$, the termination criterion \eqref{eq:actual_termi} holds whenever
    \begin{align}
        \frac{6(\sigma+1)\beta D_X^2}{t-1} + \frac{\sigma \beta D_X^2}{t} \le \eta.
    \end{align}
    Noting the definition of $T$ \eqref{def:T}, the above condition clearly holds for all $t\ge T$.
\end{proof}

\begin{lemma}\label{lem:LkLB}
For any $\delta >0$ and any $L$ such that
\begin{align}
    L \geq \left( \frac{1-\nu}{1+\nu}\cdot\frac{1}{\tau}\right)^{\frac{1-\nu}{1+\nu}} M_\nu ^ \frac{2}{1+\nu},
\end{align} 
where $\nu$ and $M_\nu$ are the H\"older continuity exponent and constant in \eqref{def:holderCont}, we have
\begin{equation}\label{eq:LkUB}
    f(y)\leq f(x) + \ip{\grad f(x), y-x} + \frac{L}{2}\norm{y-x}^2 + \frac{\tau}{2}, \ \forall x,y \in X.
\end{equation}
\end{lemma}

\begin{proof}
    See Lemma 1 of \cite{nesterov2015universal}.
\end{proof}

\begin{corollary}\label{coro:LkLB}
    Any $L_k>0$ chosen by Algorithm \ref{alg:UCGS} according to \eqref{def:lk} must also satisfy
    \begin{align}
        L_k \leq 2\left(\frac{1-\nu}{1+\nu}\cdot\frac{1}{\varepsilon \gamma_k}\right)^{\frac{1-\nu}{1+\nu}} M_\nu^{\frac{2}{1+\nu}}
    \end{align}
\end{corollary}

\begin{proof}
    Suppose that $L_k$ does not satisfy \eqref{eq:LkUB}.  Then applying Proposition \ref{prop:flkDiff}  with $\tau = \varepsilon \gamma_k$ implies that $L_k/2$ satisfies \eqref{def:lk}, contradicting the fact that $L_k$ was chosen at step $k$ following the proposed backtracking linesearch implementation (see the remark on practical implementation after the description of Algorithm \ref{alg:UCGS}). 
\end{proof}

\begin{lemma}\label{lem:lkgammak}
    Let $L_k>0$ be chosen by \eqref{def:lk} of Algorithm \ref{alg:UCGS} at step $k$, then
    \begin{align}
        L_k\gamma_k^2 \leq \frac{C_\nu M_\nu^{\frac{2}{1+\nu}}}{k^{\frac{1+3\nu}{1+\nu}}\varepsilon^{\frac{1-\nu}{1+\nu}}} 
    \end{align}
    where 
    \begin{align}\label{eq:c}
        C_\nu := \left( \frac{1+2\nu}{1+3\nu}\right)^{\frac{1+3\nu}{1+\nu}}\left(\frac{1-\nu}{1+\nu}\right)^\frac{1-\nu}{1+\nu}2^{\frac{4+10\nu}{1+\nu}} 
    \end{align}
    is a constant depending only on $\nu$. 
\end{lemma}

\begin{proof}
    The case when $k=1$ is immediate from Corollary \ref{coro:LkLB}. Therefore, throughout the proof we will assume that $k\ge 2$.
    Since we set $\Gamma_k = L_k\gamma_k^2/k$ in Algorithm \ref{alg:UCGS}, we can prove this proposition by bounding $\Gamma_k$. 
    Set $s:= (1+\nu)/(1+3\nu)$.  Since $\nu \in [0,1]$, we have $s\in [{1}/{2},1]$.
    % \begin{align}
    %     \frac{1}{2} = \frac{1}{3}\left(1+\frac{2}{1+3}\right) \leq \frac{1}{3}\left(1+\frac{2}{1+3\nu}\right) = \frac{1}{3}\left(\frac{3+3\nu}{1+3\nu}\right) = s < 1.
