    \end{align}
    and the definition of $C_\nu$ in \eqref{eq:c}, we obtain
    \begin{align}
        \frac{1}{\Gamma_k^s} \geq \frac{1}{\Gamma_k^s} - \frac{1}{\Gamma_{1}^s} 
        &
        \geq 
        % \left(\frac{1+\nu}{1-\nu}\right)^\frac{1-\nu}{1+3\nu}\frac{\varepsilon^\frac{1-\nu}{1+3\nu}}{2^\frac{2+4\nu}{1+3\nu}M_\nu^\frac{2}{1+3\nu}}\frac{1+3\nu}{4+8\nu}k^{\frac{2+4\nu}{1+3\nu}}
        % \\
