		\For {$k=1,2,\ldots,$}
		\State Decide $L_k >0$ such that
		\begin{align}
			f(y_k) \leq f(z_k) + \ip{\grad f(z_k),y_k-z_k} + \frac{L_k}{2}\norm{y_k-z_k}^2 + \frac{\varepsilon}{2}\gamma_k\label{def:lk}
		\end{align}
		\State where 
		\begin{align}
			\label{def:gammak} \gamma_k &:= \begin{cases} 1, &k = 1\\ \text{positive solution to } \Gamma_{k-1}(1-\gamma_k)=\frac{L_k\gamma_k^2}{k}, &k > 1 \end{cases}\\
			\label{def:zk} z_k &:= (1-\gamma_k)y_{k-1} + \gamma_k x_{k-1}\\
			\label{def:xk} x_k &:= \text{ACGM}(\grad f(z_k), x_{k-1},\beta_k,\eta_k)\\
			\label{def:yk} y_k &:= (1-\gamma_k)y_{k-1} + \gamma_k x_k\\
			\label{def:Gammakk}\Gamma_k &:= \frac{L_k\gamma_k^2}{k}.
		\end{align}

		\State 
		Compute an approximate solution $s_k$ to the problem 
		\begin{align}
		    \label{def:lkproblem}
		    \min_{x\in X}\ell_k(x) := \Gamma_k \sum_{i=1}^k \frac{\gamma_i}{\Gamma_i}\left( f(z_i) + \ip{\grad f(z_i),x-z_i}\right)
		\end{align}
		such that $\ell_k(s_k) - \min_{x\in X}\ell_k(x)\le \varepsilon_k$. Terminate and output $y_k$ as an approximate solution if
		\begin{align}\label{eq:stopCrit}
			f(y_k) - \ell_k(s_k) + \varepsilon_k \leq \varepsilon.
		\end{align}
		\EndFor
		\\


		\Procedure{$u^+ =$ ACGM}{$g,u,\beta, \eta$} 
		\State Goal: Compute $u^+$ such that $\max_{x\in X}\ip{\grad\phi(u^+), u^+-x}\le \eta$, where
		\begin{align}
		    \label{def:phi}
		    \phi(x):=\ip{g, x} + \frac{\beta}{2}\|x - u\|^2.
		\end{align}
		\State Start: Set $u^0 = u$. 
