		\State Compute a $\delta^t$-approximate solution $v^t$ to the problem $\min_{x\in X}\ip{\nabla\phi(u^{t-1}),x}$ such that
		\begin{equation}\label{eq:cndgsubproblem}
			\ip{g + \beta(u^{t-1}-u),v^t} - \min_{x\in X}\ip{g + \beta(u^{t-1}-u), x}  \leq \delta^t.
		\end{equation}

		\State Terminate with $u^+:=u^{t-1}$ if
		\begin{align}
		    \label{eq:actual_termi}
		    \ip{g+\beta(u^{t-1}-u),u^{t-1}-v^t} + \delta^t \leq \eta.
		\end{align}
