\begin{proposition}\label{prop:flkDiff}
    Suppose that the parameters in Algorithm \ref{alg:UCGS} satisfy $\beta_k \geq L_k \gamma_k$ for all $k$. Then for any $x\in X$, 
    \begin{align}
        f(y_k) - \ell_k(x) \leq \frac{\varepsilon}{2} + \Gamma_k \sum_{i=1}^k \frac{\gamma_i\beta_i}{2\Gamma_i}\left(\norm{x-x_{i-1}}^2 - \norm{x-x_i}^2\right)^2 + \Gamma_k \sum_{i=1}^k \frac{\gamma_i\eta_i}{\Gamma_i}.
    \end{align} 
\end{proposition}

\begin{proof}
    Fix any $x\in X$. From the definitions of $\ell_k(x)$ and $y_k$ in \eqref{def:lk} and \eqref{def:yk} respectively, we have
    \begin{align}
        \frac{1}{\Gamma_k}\ell_k(x) =& \sum_{i=1}^k \frac{1}{\Gamma_i}\left( \gamma_i f(z_i) + \gamma_i \ip{\grad f(z_i),x-x_i} + \ip{\grad f(z_i),\gamma_i(x_i-z_i)}\right)\\
        =& \sum_{i=1}^k \frac{1}{\Gamma_i}\left( f(z_i) + \ip{\grad f(z_i), y_i-z_i}\right)+ \frac{\gamma_i}{\Gamma_i} \ip{\grad f(z_i),x-x_i}
        \\
        &\qquad- \frac{1-\gamma_i}{\Gamma_i}(f(z_i) + \ip{\grad f(z_i), y_{i-1}-z_i})
    \end{align}
    We will now bound three terms in the above relation.  First, by convexity of $f$, 
    \begin{align}
        -(f(z_i) + \ip{\grad f(z_i),y_{i-1}-z_i}) \ge -f(y_{i-1}).
    \end{align}
    Second, by our choice of $L_k$ in \eqref{def:lk} and the definitions of $y_k$ and $z_k$ in \eqref{def:yk} and \eqref{def:zk} respectively, we have
    \begin{align}
        f(z_i) + \ip{\grad f(z_i),y_i-z_i} \ge & f(y_i) - \frac{L_i}{2}\norm{y_i-z_i}^2 - \frac{\varepsilon}{2}\gamma_i 
        \\
        = & f(y_i) - \frac{L_i\gamma_i^2}{2}\norm{x_i-x_{i-1}}^2 - \frac{\varepsilon}{2}\gamma_i.
    \end{align}
    Lastly, using the result \eqref{eq:innerIterUCGS_OC} in Lemma \ref{lem:innerIterUCGS} and noting the definition of $\phi(x)$ in \eqref{def:phi}, we obtain the following result during the termination of the ACGM procedure in computing $x_i$:
    \begin{align}
         \ip{\grad f(z_i), x-x_i} \geq&\: \beta_i\ip{x_i-x_{i-1},x_i-x} - \eta_i\\
        =& -\frac{\beta_i}{2}\left(\norm{x-x_{i-1}}^2 - \norm{x_i-x_{i-1}}^2 - \norm{x-x_i}^2\right) - \eta_i\\
        \geq& -\frac{\beta_i}{2}\left(\norm{x-x_{i-1}}^2 - \norm{x-x_i}^2\right) -\eta_i + \frac{L_i^2}{2}\norm{x_i-x_{i-1}}^2.
    \end{align}
    In the last inequality above we use our assumption that $\beta_k\geq L_k\gamma_k$ for all $k$. Based on the above three observations and rearranging terms we obtain that
    \begin{align}
        \frac{1}{\Gamma_k}\ell_k(x) \geq& \sum_{i=1}^k \frac{1}{\Gamma_i}\left( f(y_i) - (1-\gamma_i)f(y_{i-1}) - \frac{\gamma_i\beta_i}{2}(\norm{x-x_{i-1}}^2-\norm{x-x_i}^2)\right)
        \\
        &\qquad -\frac{1}{\Gamma_i}\left(\frac{\varepsilon}{2}\gamma_i + \gamma_i\eta_i\right)
        \\
        = & 
        \frac{f(y_k)}{\Gamma_k} -
        \sum_{i=1}^k \frac{\gamma_i\beta_i}{2\Gamma_i}(\norm{x-x_{i-1}}^2 - \norm{x-x_i}^2) -\sum_{i=1}^k \frac{\gamma_i\eta_i}{\Gamma_i} - \frac{\varepsilon}{2\Gamma_k}.
    \end{align}
    Here in the last equality we use the relations \eqref{eq:GammaRelation} and \eqref{eq:gammaSum} and the fact that $\gamma_1=1$ in its definition \eqref{def:gammak}. We conclude the result by multiplying by $\Gamma_k$ and rearranging  terms.
\end{proof}

